WITH drug1_source AS (
  SELECT concept_id FROM omop.concept WHERE vocabulary_id = 'RxNorm' AND concept_code = '313782' AND invalid_reason IS NULL
), drug1_mapped AS (
  SELECT concept_id_2 AS concept_id FROM drug1_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to'
), drug1_concepts AS (
  SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug1_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
),
drug2_source AS (
  SELECT concept_id FROM omop.concept WHERE vocabulary_id = 'RxNorm' AND concept_code = '1483571' AND invalid_reason IS NULL
), drug2_mapped AS (
  SELECT concept_id_2 AS concept_id FROM drug2_source ds JOIN omop.concept_relationship cr ON ds.concept_id = cr.concept_id_1 WHERE cr.relationship_id = 'Maps to'
), drug2_concepts AS (
  SELECT DISTINCT ca.descendant_concept_id AS concept_id FROM drug2_mapped dm JOIN omop.concept c ON dm.concept_id = c.concept_id JOIN omop.concept_ancestor ca ON c.concept_id = ca.ancestor_concept_id
)
SELECT COUNT(DISTINCT dr1.person_id) AS patient_count
FROM omop.drug_exposure dr1
JOIN drug1_concepts dc1 ON dr1.drug_concept_id = dc1.concept_id
JOIN omop.drug_exposure dr2 ON dr1.person_id = dr2.person_id
JOIN drug2_concepts dc2 ON dr2.drug_concept_id = dc2.concept_id;
